import{_ as e,o as i,c as r,a2 as o}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Sastrería","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/professions/tailoring.md","filePath":"es/guide/professions/tailoring.md"}'),t={name:"es/guide/professions/tailoring.md"};function s(n,a,l,d,c,p){return i(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="tailoring" tabindex="-1">Sastrería <a class="header-anchor" href="#tailoring" aria-label="Enlace permanente a &quot;Sastrería&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · No establecido como jugable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Transforma cuero, tela, fibras y acolchado en ropa y protección flexible.</li><li>El ajuste, la costura y las reparaciones dan valor a la sastrería durante las expediciones.</li><li>La función, la moda y el conocimiento de materiales son caminos hacia la reputación.</li></ul><p><span id="what-it-does"></span><span id="why-take-it-into-the-field"></span><span id="learning-and-specialization"></span><span id="progression-and-related-crafts"></span></p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Actividad</th><th>Qué haces</th></tr></thead><tbody><tr><td>Preparar materiales</td><td>Obtén, conserva, procesa y clasifica pieles o fibras.</td></tr><tr><td>Fabricar y ajustar</td><td>Corta, monta, ajusta y acaba prendas o armaduras flexibles.</td></tr><tr><td>Ampliar conocimientos</td><td>Un diario de materiales y sastrería registra tratamientos, confección y estilos.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Dirección de Syrolands</th></tr></thead><tbody><tr><td>La tela y el cuero se convierten en ropa y armaduras mediante fabricación.</td><td>La conservación, el procesamiento y el ajuste se convierten en decisiones relevantes del oficio.</td></tr><tr><td>La ropa, los tintes y las armaduras de cuero ya ofrecen identidad y protección.</td><td>El tratamiento del material y el mantenimiento amplían esas funciones sin una bonificación plana de armadura.</td></tr></tbody></table><p>La comparación usa los ciclos conocidos de los oficios de UO; las referencias oficiales también cubren expansiones posteriores. <a href="https://uo.com/wiki/ultima-online-wiki/skills/tailoring/" target="_blank" rel="noreferrer">Tailoring</a>.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Un sastre de expedición podría coser y reajustar equipo de cuero dañado. Un especialista en moda podría hacerse conocido por un corte o bordado distintivo de gremio.</p><h2 id="progression-and-trade-offs" tabindex="-1">Progresión y compromisos <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Enlace permanente a &quot;Progresión y compromisos&quot;">​</a></h2><ul><li>El daño a una criatura puede afectar a su piel. Anatomy y Animal Lore podrían orientar la obtención de materiales; no se ha decidido una habilidad de desuello separada.</li><li>La protección flexible debe diferenciarse de las placas. Las reglas de obtención, ajuste y capas siguen abiertas; Alquimia puede aportar tratamientos y tintes.</li></ul><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/professions/alchemy.html">Alquimia</a> · <a href="/Syrolands-Public/es/guide/professions/carpentry.html#bowmaking-and-fletching">Fabricación de arcos</a> · <a href="/Syrolands-Public/es/guide/items/item-quality.html">Calidad de objetos</a> · <a href="/Syrolands-Public/es/guide/professions/overview.html">Sistema de profesiones</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/professions/tailoring.html">Sastrería</a></p>',18)])])}const m=e(t,[["render",s]]);export{h as __pageData,m as default};
